<?php require 'common.php'; try{$in=body_json();$items=$in['items']??[];if(!$items)throw new Exception('Collection is empty.');$tmp=tempnam(sys_get_temp_dir(),'insta_');$zip=new ZipArchive();if($zip->open($tmp,ZipArchive::CREATE)!==true)throw new Exception('Could not create ZIP.');$used=[];foreach($items as $x){$u=clean_user($x['username']??'unknown_user');$fn=basename($x['filename']??filename_for($x));$entry=$u.'/'.$fn;$base=pathinfo($entry,PATHINFO_DIRNAME).'/'.pathinfo($entry,PATHINFO_FILENAME);$ext=pathinfo($entry,PATHINFO_EXTENSION);$n=1;while(isset($used[$entry])){$entry=$base.'_'.$n.'.'.$ext;$n++;}$used[$entry]=1;$zip->addFromString($entry,http_get($x['url'],90));usleep(300000);} $zip->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="instagram_media_collection.zip"');header('Content-Length: '.filesize($tmp));readfile($tmp);unlink($tmp);}catch(Throwable $e){send_json(['ok'=>false,'error'=>$e->getMessage()],500);}
